vec2 scale(vec2 srcTex, vec2 center, float ratio)
{
    return (srcTex - center) / ratio + center;
}

vec4 blendNormal(vec4 c2, vec4 c1) {
    vec4 outputColor;
    outputColor.r = c1.r + c2.r * c2.a * (1.0 - c1.a);
    outputColor.g = c1.g + c2.g * c2.a * (1.0 - c1.a);
    outputColor.b = c1.b + c2.b * c2.a * (1.0 - c1.a);
    outputColor.a = c1.a + c2.a * (1.0 - c1.a);
    return outputColor;
}

vec3 blendAdd(vec3 src1, vec3 src2, float alpha)
{
    return src1 + src2 * alpha;
}

vec3 blendMultiply(vec3 src1, vec3 src2, float alpha)
{
    return src1 * (1.0 - alpha) + src1 * src2 * alpha;
}

vec3 blendScreen(vec3 src1, vec3 src2, float alpha)
{
    return src1 + src2 * alpha - src1 * src2 * alpha;
}

vec3 blendOverlay(vec3 src1, vec3 src2, float alpha)
{
