}

vec3 blendSoftLight(vec3 src1, vec3 src2, float alpha)
{
    return mix(src1, src1 * (alpha * src1 + (2.0 * src2 * (1.0 - src1))) + src1 * (1.0 - alpha), alpha);
}

vec3 blendHardLight(vec3 src1, vec3 src2, float alpha)
{
    vec3 src1x2 = src1 * src2 * alpha * 2.0;
    src2 = mix(src1x2, ((src1 * alpha + src2 * alpha) * 2.0 - src1x2 - alpha), step(0.5 * alpha, src2 * alpha));
    return src1 * (1.0 - alpha) + src2;
}

vec3 blendColorDodge(vec3 src1, vec3 src2, float alpha)
{
    src2 = clamp(src2 * alpha, 0.0, alpha - 0.001);
