Enlargement = {}

function Enlargement:matchWithId(effectId)
    return 'KFM KSkr Enlargement' == effectId
end

function Enlargement.createWithId(effectId)
    if not Enlargement:matchWithId(effectId) then
        return nil
    end
    local o = {
        program = {},
        vertexBuffer = 0
    }
    o = newObject(o, Enlargement)
    o:init()
    return o;
end

function Enlargement:init()
    local buffer = {}
    glGenBuffers(1, buffer)
    self.vertexBuffer=buffer[1]

    local vertexBufferData = CGE.FloatBuffer:alloc(8)
    vertexBufferData:put(8, { -1, -1, 1, -1, -1, 1, 1, 1}, 0)
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glBufferData(GL_ARRAY_BUFFER, 8, vertexBufferData, GL_STATIC_DRAW)

    self.program = CGE.ProgramObject()
    self.program:bindAttribLocation("vPosition", 0)
    self.program:initWithShaderStrings(s_vsh, s_fsh)
end

function Enlargement:onDestroy()
    glDeleteBuffers(1, {self.vertexBuffer})
end

function Enlargement:valueType(index)
    if index == 1 then
        --shape
        return FM.AEValueType_OneDInt
    elseif index == 2 then
        --center
        return FM.AEValueType_TwoD
    elseif index == 3 then
        --ratio
        return FM.AEValueType_OneDFloat
    elseif index == 4 then
        --link
        return FM.AEValueType_OneDInt
    elseif index == 5 then
        --size
        return FM.AEValueType_OneDFloat
    elseif index == 6 then
        --feather
        return FM.AEValueType_OneDFloat
    elseif index == 7 then
        --alpha
        return FM.AEValueType_OneDFloat
    elseif index == 8 then
        --blendMode
        return FM.AEValueType_OneDInt
    end
end

function Enlargement:updateValue(index, val1, val2, val3)
    self.program:bind()
    if index == 1 then
        --shape
        self.program:sendUniformi("shape", (val1 - 1))
    elseif index == 2 then
        -- center
        self.program:sendUniformf("center1", val1, val2)
    elseif index == 3 then
        -- ratio
        self.program:sendUniformf("ratio1", val1)
    elseif index == 4 then
        -- link
        self.program:sendUniformi("link", (val1 - 1))
    elseif index == 5 then
        -- size
        self.program:sendUniformf("size", val1)
    elseif index == 6 then
        -- feather
        self.program:sendUniformf("feather", val1)
    elseif index == 7 then
        -- alpha
        self.program:sendUniformf("alpha1", val1)
    elseif index == 8 then
        -- blendMode
        self.program:sendUniformi("blendMode", (val1 - 1))
    end
end

function Enlargement:resize(width, height)
    self.program:bind()
    self.program:sendUniformf("fboSize", width, height)
end

function Enlargement:render(outFBO, inputTex)
    glBindFramebuffer(GL_FRAMEBUFFER, outFBO)
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glEnableVertexAttribArray(0)
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, 0)
    glActiveTexture(GL_TEXTURE0)
    glBindTexture(GL_TEXTURE_2D, inputTex)
    self.program:bind()
    glDrawArrays(GL_TRIANGLE_STRIP, 0, 4)
end
